solution:
def count_triangles(sides: list[int]) -> int:
    a = sorted(sides)
    count = 0
    for k in range(2, len(a)):               # a[k] is the longest side
        lo, hi = 0, k - 1
        while lo < hi:
            if a[lo] + a[hi] > a[k]:
                count += hi - lo             # every left end in lo..hi-1 works with hi too
                hi -= 1
            else:
                lo += 1                      # a[lo] is too short even with a[hi]
    return count

perf.naive:
def count_triangles(sides: list[int]) -> int:
    n = len(sides)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a, b, c = sides[i], sides[j], sides[k]
                if a + b > c and a + c > b and b + c > a:
                    count += 1
    return count
